// @vitest-environment node
import { existsSync, readFileSync } from 'node:fs'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { beforeAll, describe, expect, it } from 'vitest'

/** palette.css is generated by scripts/gen-palette.mjs from palette.ref.cjs: the file on disk must be its exact output. */
const CSS = fileURLToPath(new URL('./palette.css', import.meta.url))
const GEN = pathToFileURL(fileURLToPath(new URL('../../scripts/gen-palette.mjs', import.meta.url))).href

let render: () => string
beforeAll(async () => {
  const mod = (await import(/* @vite-ignore */ GEN)) as { render: () => string }
  render = mod.render
})

describe('palette.css is in step with its generator', () => {
  it('exists', () => {
    expect(existsSync(CSS), 'palette.css missing: run `npm run gen:palette`').toBe(true)
  })

  it('is exactly what gen-palette.mjs produces (else: `npm run gen:palette`)', () => {
    expect(readFileSync(CSS, 'utf8')).toBe(render())
  })

  it('a value edited by hand would fail the comparison (positive control)', () => {
    const out = render()
    const edited = out.replace(/(--text: oklch\()0\./, '$10.0')
    expect(edited).not.toBe(out)
    expect(edited === render()).toBe(false)
  })
})
